function inspect(past=false){modal(`<div class="eyebrow">${past?'22':'23'} OCT 2026 · JOU797</div><h2>Checklist de inicio de jornada</h2><p>Registrado por Oscar Silva · ${past?'07:28':'07:42'}</p><div class="notice amber"><b>27 puntos revisados · 2 novedades</b></div><div class="section">${Object.entries(dailyCatalog).map(([g,items])=>`<details ${g==='Iluminación'?'open':''}><summary>${g}</summary><div>${items.map(n=>`<div class="row"><div class="grow"><b class="tiny">${n}</b>${n==='Luces altas'||n==='Luces bajas'?'<p>Funcionamiento intermitente.</p>':''}</div>${badge(n==='Luces altas'||n==='Luces bajas'?'Con novedad':'Buen estado',n==='Luces altas'||n==='Luces bajas'?'amber':'green')}</div>`).join('')}</div></details>`).join('')}</div><div class="actions section">${btn('Cerrar','close')}${role==='admin'?btn('Asignar actividad','modalCreate','primary','plus'):''}</div>`)}
function decision(yes){modal(`<h2>${yes?'Autorizar salida':'No autorizar salida'}</h2><p>JOU797 · Oscar Silva · Checklist del 23 de octubre</p><form data-form="${yes?'approve':'reject'}">${area('Observación de la decisión','Registra el motivo de tu decisión…','required')}<div class="formfoot"><span class="muted tiny">Simulación · No afecta la operación real.</span><button class="btn ${yes?'primary':'danger'}" type="submit">Confirmar decisión</button></div></form>`)}
function assignment(n=false){modal(`<h2>${n?'Registrar vehículo':'Asignar vehículo a conductor'}</h2><p>La asignación puede cambiar entre jornadas.</p><form data-form="assignment"><div class="formgrid">${field('Placa','text',n?'':v().plate,'required')}${field('Descripción','text',n?'':v().model,'required')}${field('Kilometraje','number',n?'':'66950','min="0" required')}${select('Conductor',['Seleccionar conductor','Oscar Silva','Diana Rojas','Carlos Mora'],'required id="assignedDriver"')}</div><div class="section">${notice('Demostración de reasignación','En el programa no se permite cambiar el vehículo si existe una jornada abierta.','blue')}</div><div class="formfoot">${btn('Cancelar','close')}<button class="btn primary" type="submit">Guardar asignación · demo</button></div></form>`)}
function mapViews(){modal(`<div class="eyebrow">EXPLORA LA PROPUESTA</div><h2>Todas las vistas del módulo</h2><p>Selecciona un rol en la barra superior. Los botones y formularios simulan el recorrido, sin guardar información en la aplicación.</p><div class="maplist">${Object.entries(routes).map(([r,n])=>btn(n,'map:'+r,'small','arrow')).join('')}</div><div class="section">${btn('Reiniciar demostración','reset','','history')}</div>`)}
function handleAction(a){if(a.startsWith('vehicle:')){selected=+a.split(':')[1];go('vehiculo');return}if(a.startsWith('map:')){closeModal();go(a.slice(4));return}if(a.startsWith('photo:')){const [,k,t]=a.split(':');document.querySelector('#'+(t==='camera'?'cam-':'file-')+k).click();return}switch(a){case'close':closeModal();break;case'assign':assignment();break;case'newVehicle':assignment(true);break;case'approve':decision(true);break;case'reject':decision(false);break;case'inspectToday':inspect();break;case'inspectPast':inspect(true);break;case'modalCreate':closeModal();go('crear');break;case'driverTask':role='driver';document.querySelector('#role').value=role;go('tarea');break;case'verify':modal(`<h2>Verificar y cerrar</h2><p>Confirma la reparación después de revisar la evidencia.</p><form data-form="verify">${area('Observación de verificación','Indica el resultado de la revisión…','required')}<div class="formfoot"><button class="btn primary" type="submit">Cerrar actividad · demo</button></div></form>`);break;case'reopen':modal(`<h2>Solicitar corrección</h2><p>La actividad volverá a estar pendiente para el conductor.</p><form data-form="reopen">${area('¿Qué debe corregirse?','Describe qué falta por solucionar…','required')}<div class="formfoot"><button class="btn primary" type="submit">Solicitar corrección · demo</button></div></form>`);break;case'evidence':modal(`<h2>Evidencia del registro</h2><p>Vista de ejemplo del enlace al archivo almacenado en Drive.</p><div class="upload">${icon('file')} <b>Evidencia_JOU797.pdf</b><p class="muted tiny section">Ubicación: TRANSPORTE / JOU797 / Octubre 2026</p></div><p class="section">El mockup no conecta con Drive ni abre archivos reales.</p>${btn('Cerrar','close','primary')}`);break;case'assignmentHelp':toast('El administrador realiza la reasignación una vez cerrada la jornada.');break;case'readAlerts':document.querySelector('.unread').style.display='none';toast('Avisos marcados como leídos en la demostración.');break;case'extraCamera':case'extraFile':document.querySelector('#'+a).click();break;case'nextstep':saveDraft();step=Math.min(6,step+1);render();break;case'prevstep':saveDraft();step=Math.max(0,step-1);render();break;case'finishCheck':if(Object.keys(answers).length<27){toast(`Faltan ${27-Object.keys(answers).length} puntos por revisar.`);break}modal(`<h2>Enviar ${route==='cierre'?'cierre':'inspección'} de jornada</h2><p>27 puntos completados · ${Object.values(answers).filter(x=>x==='Con novedad').length} con novedad.</p><form data-form="finishCheck">${area('Observaciones de las novedades','Describe las novedades detectadas…',Object.values(answers).includes('Con novedad')?'required':'')}${route==='cierre'?select('¿Ocurrió un siniestro vial?',['No','Sí'],'id="accident"'):''}<div class="formfoot"><button class="btn primary" type="submit">Enviar checklist · demo</button></div></form>`);break;case'finishKit':if(Object.keys(kitAnswers).length<50){toast(`Quedan ${50-Object.keys(kitAnswers).length} elementos por revisar.`);break}toast('Revisión semanal completada en la demostración.');go('inicio');break;case'kitPreview':modal(`<h2>Revisión semanal de carretera</h2><p>JOU797 · 19 oct 2026 · Oscar Silva</p>${notice('50 puntos revisados','48 en buen estado · 2 no aplican. Registro de ejemplo.','blue')}<div class="section">${[...new Set(kitCatalog.map(x=>x.categoria))].map(g=>`<details><summary>${g}</summary><div>${kitCatalog.filter(x=>x.categoria===g).map(x=>`<div class="row"><div class="grow tiny">${esc(x.nombre)}</div>${badge('Revisado','green')}</div>`).join('')}</div></details>`).join('')}</div>`);break;case'selectAll':document.querySelectorAll('[data-history]').forEach(x=>{if(!x.closest('[data-day]').hidden){x.checked=true;historySelected.add(x.dataset.history)}});updateSelected();break;case'filterHistory':filterHistory();break;case'export':if(!historySelected.size){toast('Selecciona al menos una jornada para preparar el informe.');break}modal(`<h2>Informe listo para preparar</h2><p>${historySelected.size} jornadas seleccionadas · Vista previa de la estructura del Excel.</p>${['Jornadas · fecha, vehículo, conductor y registros','Checklist · inicio y fin de jornada, respuestas y novedades','Registro diario · observaciones y enlaces a las fotografías','Novedades · descripción, fecha y evidencia','Mantenimiento · intervención, costos y enlaces'].map(x=>row('file',x,'Solo las hojas y columnas con información.')).join('')}<div class="section">${notice('Propuesta visual de exportación','Este mockup no genera el Excel real. Los documentos y fotografías se exportarán como enlaces.','blue')}</div>`);break;case'reset':location.href=location.pathname;break;}}
function updateSelected(){const e=document.querySelector('#selectedCount');if(e)e.textContent=historySelected.size}
function filterHistory(){const f=document.querySelector('#historyFrom').value,t=document.querySelector('#historyTo').value;if(f&&t&&f>t){toast('La fecha inicial no puede ser posterior a la final.');return}document.querySelectorAll('[data-day]').forEach(e=>e.hidden=(f&&e.dataset.day<f)||(t&&e.dataset.day>t));toast('Filtro de fechas aplicado.');}
function filterFleet(){const q=(document.querySelector('#fleetSearch')?.value||'').toLowerCase();let n=0;document.querySelectorAll('[data-vehicle]').forEach(e=>{const ok=e.dataset.vehicle.toLowerCase().includes(q)&&(filter==='Todos'||filter==='Por autorizar'&&e.dataset.state==='Pendiente de aprobación'||filter==='Autorizados'&&e.dataset.state==='Autorizado'||filter==='Sin checklist'&&e.dataset.state==='Sin checklist');e.hidden=!ok;if(ok)n++});document.querySelector('#fleetEmpty').hidden=n>0;}
document.addEventListener('click',e=>{const g=e.target.closest('[data-go]');if(g){go(g.dataset.go);return}const a=e.target.closest('[data-action]');if(a){handleAction(a.dataset.action);return}const st=e.target.closest('[data-step]');if(st){saveDraft();step=+st.dataset.step;render()}const ks=e.target.closest('[data-kitstep]');if(ks){saveDraft();kitStep=ks.dataset.kitstep;render()}const fl=e.target.closest('[data-filter]');if(fl){filter=fl.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('on',x===fl));filterFleet()}});
document.addEventListener('input',e=>{if(e.target.id==='fleetSearch')filterFleet()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.check){saveDraft();(el.dataset.check==='daily'?answers:kitAnswers)[el.dataset.name]=el.value;const pos=window.scrollY;render();window.scrollTo(0,pos)}if(el.dataset.history){el.checked?historySelected.add(el.dataset.history):historySelected.delete(el.dataset.history);updateSelected()}if(el.dataset.photo&&el.files[0]){const f=el.files[0];if(!f.type.startsWith('image/')){toast('Selecciona un archivo de imagen.');return}const u=URL.createObjectURL(f);urls.push(u);photos[el.dataset.photo]=u;document.querySelector('#preview-'+el.dataset.photo).innerHTML=`<img src="${u}" alt="Foto seleccionada">`;document.querySelector('#state-'+el.dataset.photo).textContent='Lista';const c=document.querySelector('#photoCount');if(c)c.textContent=Object.keys(photos).filter(k=>k.startsWith('daily')).length+' de 5 fotos';toast('Foto preparada localmente. No se ha subido ningún archivo.')}if((el.id==='extraCamera'||el.id==='extraFile')&&el.files[0])document.querySelector('#extraName').textContent=el.files[0].name+' · preparado localmente';});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const t=f.dataset.form;if(t==='solution'&&!photos.solution){toast('Agrega una foto de la solución.');return}if(t==='create'&&!f.querySelector('[name=motivo]:checked')){toast('Selecciona al menos un motivo de corrección.');return}if(t==='assignment'&&document.querySelector('#assignedDriver').value==='Seleccionar conductor'){toast('Selecciona un conductor de la lista.');return}if(t==='approve'||t==='reject')departure=t==='approve'?'Autorizado':'No autorizado';if(t==='verify')activityState='Cerrada';if(t==='reopen'||t==='create')activityState='Pendiente';if(t==='solution')activityState='Por verificar';let accident=false;if(t==='finishCheck'){accident=document.querySelector('#accident')?.value==='Sí';if(route==='cierre')journeyEnd=true;else{journeyStart=true;departure='Pendiente de aprobación'}}closeModal();toast('Simulación completada. No se modificaron datos de la aplicación.');go(accident?'siniestro':['solution','verify','reopen'].includes(t)?'tarea':t==='create'?'actividades':t==='approve'||t==='reject'?'revision':t==='documents'?'documentos':t==='assignment'?'flota':t==='finishCheck'?'inicio':'historial')});
document.querySelector('#role').addEventListener('change',e=>{role=e.target.value;selected=0;go('inicio')});document.querySelector('#guide').onclick=mapViews;document.querySelector('#menu').onclick=()=>document.body.classList.toggle('menu-open');document.querySelector('.dialog-close').onclick=closeModal;document.querySelector('#dialog').addEventListener('click',e=>{if(e.target.id==='dialog'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'inicio';render();window.scrollTo(0,0)});window.addEventListener('beforeunload',()=>urls.forEach(URL.revokeObjectURL));document.querySelector('#logo').src=logo;document.querySelector('#bell').innerHTML=icon('bell');route=location.hash.slice(1)||'inicio';render();
